@Test("Xref streams, predictors and packed objects survive consecutive revisions", arguments: validXRefs)
func xrefStreamRevisions(_ encoded: String) throws {
    let bytes = try #require(Data(base64Encoded: encoded, options: .ignoreUnknownCharacters))
    #expect(try PDFFile(bytes: bytes).pages().count == 2)
    let source = FileManager.default.temporaryDirectory.appending(path: UUID().uuidString)
    let target = source.appendingPathExtension("out")
    defer {
        try? FileManager.default.removeItem(at: source)
        try? FileManager.default.removeItem(at: target)
    }
    try bytes.write(to: source)
    for _ in 0..<2 {
        let before = try Data(contentsOf: source)
        try PDFOverlayWriter().write(original: source, overlays: [
            .init(pageIndex: 0, content: Data("0 g 20 20 10 10 re f".utf8), states: []),
        ], to: target)
        #expect(try Data(contentsOf: target).starts(with: before))
        #expect(try PDFFile(url: target).pages().count == 2)
        let provider = try #require(CGDataProvider(url: target as CFURL))
        #expect(CGPDFDocument(provider)?.numberOfPages == 2)
        try Data(contentsOf: target).write(to: source)
    }
}

@Test("Malformed xref predictors, lengths and packed indices are refused", arguments: invalidXRefs)
func malformedXRefStreams(_ encoded: String) throws {
    let bytes = try #require(Data(base64Encoded: encoded, options: .ignoreUnknownCharacters))
    #expect(throws: PDFReadError.self) { try PDFFile(bytes: bytes).pages() }
}

@Test("Fresh navigation maps links and outline destinations after page reordering")
func freshNavigationMapping() throws {
    let bytes = try #require(Data(base64Encoded: validXRefs[0], options: .ignoreUnknownCharacters))
    let url = FileManager.default.temporaryDirectory.appending(path: UUID().uuidString)
    defer { try? FileManager.default.removeItem(at: url) }
    try bytes.write(to: url)
    let provider = try #require(CGDataProvider(data: bytes as CFData))
    let document = try #require(CGPDFDocument(provider))
    let sheet = CGSize(width: 200, height: 300)
    let navigation = try PDFNavigation(original: url, document: document,
                                       mapping: [(1, true, sheet), (0, true, sheet)])
    let data = NSMutableData()
    let consumer = try #require(CGDataConsumer(data: data))
    var box = CGRect(origin: .zero, size: sheet)
    let context = try #require(CGContext(consumer: consumer, mediaBox: &box, nil))
    for page in 0..<2 {
        context.beginPDFPage(nil)
        navigation.draw(page: page, in: context)
        context.endPDFPage()
    }
    navigation.finish(in: context)
    context.closePDF()
    let output = try PDFFile(bytes: data as Data)
    let pages = try output.pages()
    #expect(pages.count == 2)
    let annotations = try output.resolve(pages[1].dictionary["Annots"]).arrayValue
    #expect(annotations?.count == 1)
    let catalog = try #require(output.resolve(output.trailer["Root"]).dictionaryValue)
    let outline = try #require(output.resolve(catalog["Outlines"]).dictionaryValue)
    let child = try #require(output.resolve(outline["First"]).dictionaryValue)
    let destination = try #require(output.resolve(child["Dest"]).arrayValue)
    #expect(destination.first == .reference(number: pages[1].number, generation: 0))
}

@Test("Fresh local links follow reordered pages and omit removed destinations")
func freshLocalNavigation() throws {
    let original = NSMutableData()
    let consumer = try #require(CGDataConsumer(data: original))
    var box = CGRect(x: 0, y: 0, width: 200, height: 300)
    let context = try #require(CGContext(consumer: consumer, mediaBox: &box, nil))
    context.beginPDFPage(nil)
    context.setDestination("end" as CFString, for: CGRect(x: 10, y: 10, width: 20, height: 20))
    context.endPDFPage()
    context.beginPDFPage(nil)
    context.addDestination("end" as CFString, at: CGPoint(x: 25, y: 200))
    context.endPDFPage()
    context.closePDF()
    let url = FileManager.default.temporaryDirectory.appending(path: UUID().uuidString)
    defer { try? FileManager.default.removeItem(at: url) }
    try (original as Data).write(to: url)
    let provider = try #require(CGDataProvider(data: original))
    let source = try #require(CGPDFDocument(provider))
    let size = box.size
    let reordered = try PDFNavigation(original: url, document: source, mapping: [(1, true, size), (0, true, size)])
    #expect(reordered.links[1]?.count == 1)
    #expect(reordered.destinations[0]?.count == 1)
    #expect(reordered.destinations[0]?.first?.1 == CGPoint(x: 25, y: 200))
    let removed = try PDFNavigation(original: url, document: source, mapping: [(0, true, size)])
    #expect(removed.links.isEmpty)
    #expect(removed.destinations.isEmpty)
    let rotated = try #require(PDFDocument(data: original as Data))
    rotated.page(at: 1)?.rotation = 90
    let rotatedBytes = try #require(rotated.dataRepresentation())
    try rotatedBytes.write(to: url)
    let rotatedProvider = try #require(CGDataProvider(data: rotatedBytes as CFData))
    let rotatedSource = try #require(CGPDFDocument(rotatedProvider))
    let rotatedNavigation = try PDFNavigation(original: url, document: rotatedSource,
                                             mapping: [(0, true, size), (1, true, CGSize(width: 300, height: 200))])
    let point = try #require(rotatedNavigation.destinations[1]?.first?.1)
    #expect(abs(point.x - 200) < 0.0001)
    #expect(abs(point.y - 175) < 0.0001)
}

@Test("Stream decoding rejects malformed parameters and damaged compressed data")
func invalidStreamParameters() throws {
    let bytes = PDFWriter.flate(Data([1, 2, 3]))
    let options: [PDFObject] = [
        .integer(1), .array([]), .array([.null, .null]),
        .dictionary(["Predictor": .real(1.5)]),
        .dictionary(["Predictor": .integer(12), "Columns": .integer(0)]),
        .dictionary(["Predictor": .integer(12), "BitsPerComponent": .integer(16)]),
    ]
    for params in options {
        #expect(throws: PDFReadError.self) {
            try PDFStreamCodec.decode(["Filter": .name("FlateDecode"), "DecodeParms": params], bytes)
        }
    }
    #expect(throws: PDFReadError.self) {
        try PDFStreamCodec.decode(["Filter": .name("FlateDecode")], bytes.dropLast())
    }
}
